def _make(data: tuple[Any,...], skill: str) -> dict[str,Any]:
    title, grammar, words, text, prompt = data
    base={"title":title,"objective":f"Розвивай українську мову на тему «{title}».","grammar":grammar,"words":words,"source":"curated_ukrainian"}
    if skill=="grammar":
        base["objective"]=f"Точно використовуй граматичні структури: {', '.join(grammar)}."
        base["examples"]=[w[2] for w in words]
    elif skill=="vocabulary":
        base["objective"]=f"Засвой і використовуй лексику теми «{title}»."
        base["examples"]=[w[2] for w in words]
    elif skill=="reading":
        base.update(objective="Прочитай зв'язний український текст і визнач його основні думки.",text=text,questions=["Яка головна тема тексту?","Які два деталі підтверджують основну думку?","Перефразуй один висновок власними словами."])
    elif skill=="listening":
        base.update(objective="Зрозумій основну інформацію зв'язного українського тексту.",transcript=text,questions=["Яка головна думка?","Які дві важливі деталі ти почув?","Який висновок можна зробити з почутого?"])
    elif skill=="speaking":
        base.update(objective="Говори самостійно на тему, точно використовуючи українську.",prompt=prompt,phrases=[w[2] for w in words],examples=[w[2] for w in words[:2]])
    elif skill=="writing":
        base.update(objective="Напиши зв'язний текст відповідно до свого рівня української.",prompt=prompt,guidance=[f"Використай щонайменше одну структуру: {', '.join(grammar)}.","Використай щонайменше три слова з теми.","Поєднай думки чіткими реченнями."],examples=[w[2] for w in words[:2]])
    elif skill=="review":
        base.update(objective="Повтори граматику та лексику теми.",questions=[f"Склади речення з однією структурою: {', '.join(grammar)}.",f"Використай два слова з теми: {', '.join(w[0] for w in words[:2])}.","Поясни, як контекст впливає на значення вислову."])
    else:return {}
    return base

S={}
for level,units in DATA.items():
    for unit_id,data in units.items():
        for skill in ("grammar","vocabulary","reading","listening","speaking","writing","review"):
            S[(level,unit_id,skill)]=_make(data,skill)

def get_lesson_seed(level:str,unit_id:str,lesson_type:str)->dict[str,Any]|None:
    return S.get((str(level).upper(),str(unit_id),str(lesson_type).lower()))
